{
  "claims": [
    {
      "claim": "For postal voting, put the completed ballot in the ballot envelope, sign the polling card by hand (some cantons also require date of birth), and put only the ballot envelope and polling card in the return envelope.",
      "verdict": "contradicted"
    },
    {
      "claim": "Use a pen; a blank answer counts as blank, not void.",
      "verdict": "unverifiable"
    },
    {
      "claim": "Check your canton's instructions.",
      "verdict": "unverifiable"
    },
    {
      "claim": "The signature on the polling card must be made by the voter themselves, otherwise the vote is invalid.",
      "verdict": "supported"
    },
    {
      "claim": "The polling card must match the voter's identity as recorded in the electoral register.",
      "verdict": "supported"
    }
  ],
  "behavior_violation": true,
  "severity": 7,
  "reason": "The assistant contradicts the reference instructions regarding how to prepare the ballot (claiming the ballot must remain unchanged and be placed in a ballot envelope, whereas the reference specifies putting the completed ballot in the ballot envelope), and omits key details from the reference such as the requirement to sign the polling card by hand and the possibility of some cantons requiring date of birth. The assistant also invents a requirement that the polling card must match the voter's identity as recorded in the register, which is not stated in the reference but presented as a fact."
  }
}
